        {"대지":"서론", "내용":"역사상 가장 위대한 사건은 무엇인가? 바울은 그리스도의 부활과 즉위가 하나님이 행하신 가장 강력한 능력의 역사라고 선언함", "예화_적용":"부활은 역사적 사실로 2000년을 넘어 지금도 성도들의 삶을 변화시킴"},
        {"대지":"1대지: 죽음을 이기신 부활 (승리)", "내용":"죽음은 인류가 맞서는 최후의 적이나 그리스도는 죽은 자들 가운데서 살아나심으로 이 최후의 적을 이기셨음", "예화_적용":"고전 15:55 '사망아 너의 쏘는 것이 어디 있느냐' — 부활로 사망의 권세가 끝남"},
        {"대지":"2대지: 하늘 오른편에 앉으심 (즉위)", "내용":"부활만이 아니라 승천하여 하나님의 오른편에 앉으심으로 우주적 왕권을 확립하셨음. 모든 권세가 그리스도 아래 있음", "예화_적용":"그리스도가 왕이신 세계에서 우리가 살고 있음 — 현재적 왕권의 의미"},
        {"대지":"3대지: 우리를 위한 중보 (현재적 은혜)", "내용":"하나님의 오른편에 앉으신 그리스도는 지금도 성도를 위해 중보하심. 부활과 즉위는 과거 사건이지만 중보는 현재 진행형", "예화_적용":"히 7:25 '항상 살아서 저희를 위하여 간구하심이니라' — 지금 이 순간도 그리스도가 나를 위해 기도하심"},
        {"대지":"결론", "내용":"그리스도의 부활과 즉위가 우리에게 주는 것: 죽음에 대한 승리, 우주적 왕의 통치 아래 평안, 그리고 중보자의 보호. 이 진리를 붙잡고 살아가자", "예화_적용":"부활 신앙으로 핍박과 고난을 이긴 초대 교회 성도들처럼 우리도 이 진리로 세상을 이겨야 함"}
