        {"구절":"왕상 2:19", "연결점":"왕이 어머니를 위해 보좌 우편에 자리를 준비함 — 오른편 명예의 구약적 배경", "구분":"구약"},
        {"구절":"단 7:13-14", "연결점":"인자 같은 이가 권세와 영광과 나라를 받음 — 메시아 즉위의 예언", "구분":"구약"},
        {"구절":"시 16:10", "연결점":"주의 거룩한 자를 음부에 버리지 아니하시며 — 부활 예언", "구분":"구약"},
        {"구절":"행 2:33-35", "연결점":"저가 하나님의 우편에 높이 들리어 — 오순절 설교에서 부활 즉위 선포", "구분":"신약"},
        {"구절":"히 1:3", "연결점":"죄를 정결케 하는 일을 하시고 높은 곳에 계신 위엄의 우편에 앉으심 — 병행 구절", "구분":"신약"},
        {"구절":"고전 15:20", "연결점":"그리스도께서 죽은 자 가운데서 다시 사셔서 잠자는 자들의 첫 열매가 되셨도다 — 부활의 의미", "구분":"신약"},
        {"구절":"롬 8:34", "연결점":"그리스도 예수께서 죽으셨다가 다시 살아나사 하나님 우편에 계신 자요 — 중보 사역", "구분":"신약"}
