        {"교리":"하나님의 영광", "설명":"구원의 궁극적 목적은 인간의 행복이 아닌 하나님의 영광임. 은혜의 풍성함을 나타내는 것이 성도 구원의 최종 목적", "관련구절":"사 43:7, 롬 9:23, 요 17:4"},
        {"교리":"역사의 목적론", "설명":"하나님은 오는 모든 세대를 통해 자신의 은혜를 나타내시는 계획을 가지심. 역사는 우연이 아닌 이 목적을 향해 나아감", "관련구절":"엡 1:10, 3:9-11, 롬 8:28"}
