        {"대지":"결론", "내용":"구원은 내가 노력해서 얻은 것이 아니라 하나님의 은혜로, 믿음을 통해, 선물로 받은 것임. 이 진리가 교만을 제거하고 감사를 낳으며, 불안을 제거하고 평안을 줌", "예화_적용":"은혜로 구원받았다는 사실이 삶에 어떤 변화를 가져오는지 — 감사, 자유, 섬김의 동기"}
