        {"구절":"골 1:20", "연결점":"그의 십자가의 피로 화평을 이루사 — 직접적 병행 구절", "구분":"신약"},
        {"구절":"고후 5:18-19", "연결점":"하나님께서 그리스도로 말미암아 우리를 자기와 화목하게 하시고 — 화목의 근거와 사명", "구분":"신약"}
