        {"상황":"교회 안에서 소외감과 차별을 느끼는 성도", "성경원리":"그리스도 안에서 이방인도 유대인과 동등한 후사요 지체로, 교회 안에서 어떤 신자도 이류가 될 수 없음 (엡 3:6)", "실제적용":"소외된 성도에게 공동체 안에서의 실질적 역할과 소속감을 부여하는 구체적 방법 모색"},
        {"상황":"민족적 배경으로 신앙적 열등감을 느끼는 다문화 성도", "성경원리":"이방인이 유대인과 '함께' 동등한 상속자가 됨 — 혈통이나 민족이 아닌 그리스도 안의 믿음이 기준", "실제적용":"다문화 성도의 정체성을 그리스도 안에서 재정립; 각자의 문화적 배경이 교회를 풍요롭게 함을 가르침"},
        {"상황":"오랜 신앙 경력을 가진 성도가 새 신자를 무시하는 경우", "성경원리":"그리스도 안에서 모든 성도는 동등한 약속의 참예자 — 신앙 연수나 지식으로 등급을 매길 수 없음", "실제적용":"모든 성도의 동등한 존엄성 교육, 선배 성도의 섬김과 포용 역할 강조"}
