        {"대지":"서론", "내용":"좋아하는 사람이 어려움을 당할 때 우리도 낙심됩니다. 바울은 자신의 감옥 소식에 낙심한 에베소 성도들에게 말합니다: '낙심하지 말라, 이것이 너희의 영광이다!' 어떻게 고난이 영광이 될 수 있습니까?", "예화_적용":"의사가 환자를 살리기 위해 힘든 수술을 감당하는 것이 그 환자에게는 영광스러운 배려가 되는 비유"},
        {"대지":"1대지: 고난의 목적 (너희를 위한)", "내용":"바울의 고난은 자신을 위한 것이 아니라 이방인 성도들을 위한 것입니다. 목적 있는 고난은 다른 성격을 가집니다. 당신을 위해 누군가 고난받는다면 그것은 사랑의 표현입니다.", "예화_적용":"자녀를 위해 희생하는 부모의 고난 — 그 희생이 자녀에게는 사랑의 증거"},
        {"대지":"2대지: 낙심하지 말라 (엔카케인 금지)", "내용":"고난 앞에서 낙심하는 것은 자연스러운 반응이지만 영적으로는 극복해야 합니다. 낙심은 고난의 의미를 잘못 해석한 결과입니다.", "예화_적용":"마라톤에서 힘들어 포기하고 싶을 때 — 결승선을 바라볼 때 계속 달릴 수 있음"},
        {"대지":"3대지: 고난의 영광 (너희의 영광이니라)", "내용":"바울의 고난이 이방인 성도들에게 복음이 전해진 것의 영광과 연결됩니다. 고난이 다른 이에게 유익을 낳을 때 그것은 영광스러운 고난입니다.", "예화_적용":"헌혈로 낯선 이의 생명을 살린 사람 — 그 고통이 다른 이에게 생명이 되는 영광"},
        {"대지":"결론", "내용":"지금 당신이 경험하는 어려움이 다른 이들을 위한 것이라면, 그것은 이미 영광의 시작입니다. 공동체 안에서 서로의 고난을 지고 함께 영광을 향해 나아가십시오.", "예화_적용":"교회 공동체 안에서 서로의 짐을 지는 구체적인 방법들을 나눔"}
