        {"원어":"εἰς πάσας τὰς γενεὰς τοῦ αἰῶνος τῶν αἰώνων (에이스 파사스 타스 게네아스 투 아이오노스 톤 아이오논)", "의미_문법":"대대로 영원무궁하기까지 - 영원의 중복 표현으로 끝없는 영원성 강조, '시대들의 시대에' 같은 히브리적 최상급 표현", "설교포인트":"하나님의 영광은 영원히 지속되며 어떤 것도 그것을 막을 수 없음"}
